//! Vanilla's `canSurvive` / `mayPlaceOn` for placement prediction: a block
//! is only predicted where the client would place it. Which rule a block
//! follows comes from its vanilla class (`placement_rules.rs`, generated by
//! `tools/gen_placement_rules.py`).

use azalea::block::BlockState;
use azalea::block::fluid_state::{FluidKind, FluidState};
use azalea::physics::collision::BlockWithShape;
use azalea::physics::collision::sturdy::{can_support_center, is_face_sturdy, is_solid};
use azalea_core::{direction::Direction, position::BlockPos};
use azalea_registry::builtin::BlockKind;

use super::placement_rules;

const HORIZONTAL: [Direction; 4] = [
    Direction::North,
    Direction::South,
    Direction::West,
    Direction::East,
];

/// A vanilla survival rule. `Below*` look at the block underneath,
/// `*Behind` at the one the `facing` property points away from.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub(crate) enum Rule {
    /// `mayPlaceOn`: the block below is in `#<tag>`.
    BelowTag(&'static str),
    /// `CropBlock`: as `BelowTag`, with light 8+ or open sky.
    Crop(&'static str),
    Mushroom,
    Seagrass,
    SeaPickle,
    SmallDripleaf,
    BigDripleaf,
    CactusFlower,
    SugarCane,
    Cactus,
    Cocoa,
    SporeBlossom,
    Snow,
    MossyCarpet,
    Door,
    PressurePlate,
    RedstoneWire,
    /// Rails and diodes: a rigid top face below.
    RigidBelow,
    SturdyBelow,
    CenterBelow,
    SolidBelow,
    NotAirBelow,
    SturdyAbove,
    /// Ceiling hanging signs: a centre-sturdy bottom face above.
    CenterAbove,
    SturdyBehind,
    SolidBehind,
    WallHangingSign,
    /// Not predicted (vines, lichen, kelp, chorus, lily pads...): the
    /// server places these.
    Unpredicted,
}

fn id(block: BlockKind) -> &'static str {
    let name = block.to_str();
    name.strip_prefix("minecraft:").unwrap_or(name)
}

/// The block an item places: its own name, or another for seeds, carrots
/// and the like.
pub fn item_block(item: &str) -> Option<BlockKind> {
    use std::str::FromStr;
    let item = item.trim_start_matches("minecraft:");
    let id = placement_rules::item_block(item).unwrap_or(item);
    BlockKind::from_str(id)
        .ok()
        .filter(|&b| b != BlockKind::Air)
}

/// `StandingAndWallBlockItem`: the wall variant of a standing block, and
/// whether the standing one hangs from above (hanging signs).
pub fn wall_block(block: BlockKind) -> Option<(BlockKind, bool)> {
    use std::str::FromStr;
    let (wall, hangs) = placement_rules::wall_block(id(block))?;
    Some((BlockKind::from_str(wall).ok()?, hangs))
}

/// Whether placing `block` also writes its upper half (doors, tall plants).
pub fn places_upper_half(block: BlockKind) -> bool {
    placement_rules::places_upper_half(id(block))
}

pub fn is_bed(block: BlockKind) -> bool {
    placement_rules::is_bed(id(block))
}

/// Whether vanilla's `canSurvive` for the block is anything but `true`.
pub fn has_rule(block: BlockKind) -> bool {
    placement_rules::rule(id(block)).is_some()
}

/// Whether the block's placement is left to the server.
pub fn unpredicted(block: BlockKind) -> bool {
    placement_rules::rule(id(block)) == Some(Rule::Unpredicted)
}

/// `state.canSurvive(level, pos)` for a block being placed.
pub fn survives(
    state: BlockState,
    pos: BlockPos,
    block_at: &dyn Fn(BlockPos) -> Option<BlockState>,
) -> bool {
    let kind = state.as_block_kind();
    let Some(rule) = placement_rules::rule(id(kind)) else {
        return true;
    };
    let at = |d: Direction| block_at(pos + d.normal());
    let below = || at(Direction::Down);
    let tag = |s: Option<BlockState>, t: &str| s.is_some_and(|s| in_tag(s, t));
    let facing = || {
        crate::blocks::info::property(state, "facing").and_then(crate::blocks::facing::from_name)
    };
    // The block `facing` turns away from, and the face of it touched.
    let behind = || facing().map(|f| (at(f.opposite()), f));
    match rule {
        Rule::BelowTag(t) => tag(below(), t),
        Rule::Crop(t) => tag(below(), t) && crop_light(pos),
        Rule::Mushroom => {
            let Some(b) = below() else { return false };
            in_tag(b, "overrides_mushroom_light_requirement")
                || (raw_light(pos).is_none_or(|l| l < 13) && b.is_collision_shape_full())
        }
        Rule::Seagrass => {
            water_source(state_at(block_at, pos))
                && below().is_some_and(|b| {
                    is_face_sturdy(b, Direction::Up) && !in_tag(b, "cannot_support_seagrass")
                })
        }
        Rule::SeaPickle => below().is_some_and(|b| !b.is_collision_shape_empty()),
        Rule::SmallDripleaf => {
            tag(below(), "supports_small_dripleaf")
                || (water_source(state_at(block_at, pos)) && tag(below(), "supports_vegetation"))
        }
        Rule::BigDripleaf => below().is_some_and(|b| {
            matches!(
                b.as_block_kind(),
                BlockKind::BigDripleaf | BlockKind::BigDripleafStem
            ) || in_tag(b, "supports_big_dripleaf")
        }),
        Rule::CactusFlower => below().is_some_and(|b| {
            in_tag(b, "support_override_cactus_flower") || can_support_center(b, Direction::Up)
        }),
        Rule::SugarCane => {
            let Some(b) = below() else { return false };
            if b.as_block_kind() == kind {
                return true;
            }
            in_tag(b, "supports_sugar_cane")
                && HORIZONTAL.iter().any(|&d| {
                    block_at(pos.down(1) + d.normal()).is_some_and(|n| {
                        is_water_any(n) || in_tag(n, "supports_sugar_cane_adjacently")
                    })
                })
        }
        Rule::Cactus => {
            let clear = HORIZONTAL
                .iter()
                .all(|&d| at(d).is_some_and(|n| !is_solid(n) && !is_lava(n)));
            clear
                && below()
                    .is_some_and(|b| b.as_block_kind() == kind || in_tag(b, "supports_cactus"))
                && at(Direction::Up).is_some_and(|a| FluidState::from(a).kind == FluidKind::Empty)
        }
        Rule::Cocoa => facing().is_some_and(|f| tag(at(f), "supports_cocoa")),
        Rule::SporeBlossom => {
            at(Direction::Up).is_some_and(|a| can_support_center(a, Direction::Down))
                && !is_water_any(state_at(block_at, pos))
        }
        Rule::Snow => {
            let Some(b) = below() else { return false };
            if in_tag(b, "cannot_support_snow_layer") {
                return false;
            }
            in_tag(b, "support_override_snow_layer")
                || is_face_sturdy(b, Direction::Up)
                || (b.as_block_kind() == BlockKind::Snow
                    && crate::blocks::info::property(b, "layers") == Some("8"))
        }
        Rule::MossyCarpet => {
            let Some(b) = below() else { return false };
            if crate::blocks::info::property(state, "bottom") == Some("false") {
                b.as_block_kind() == kind
            } else {
                !b.is_air()
            }
        }
        Rule::Door => match crate::blocks::info::property(state, "half") {
            Some("upper") => below().is_some_and(|b| b.as_block_kind() == kind),
            _ => below().is_some_and(|b| is_face_sturdy(b, Direction::Up)),
        },
        Rule::PressurePlate => below().is_some_and(|b| {
            is_face_sturdy(b, Direction::Up) || can_support_center(b, Direction::Up)
        }),
        Rule::RedstoneWire => below().is_some_and(|b| {
            is_face_sturdy(b, Direction::Up) || b.as_block_kind() == BlockKind::Hopper
        }),
        Rule::RigidBelow | Rule::SturdyBelow => {
            below().is_some_and(|b| is_face_sturdy(b, Direction::Up))
        }
        Rule::CenterBelow => below().is_some_and(|b| can_support_center(b, Direction::Up)),
        Rule::SolidBelow => below().is_some_and(is_solid),
        Rule::NotAirBelow => below().is_some_and(|b| !b.is_air()),
        Rule::SturdyAbove => at(Direction::Up).is_some_and(|a| is_face_sturdy(a, Direction::Down)),
        Rule::CenterAbove => {
            at(Direction::Up).is_some_and(|a| can_support_center(a, Direction::Down))
        }
        Rule::SturdyBehind => {
            behind().is_some_and(|(s, f)| s.is_some_and(|s| is_face_sturdy(s, f)))
        }
        Rule::SolidBehind => behind().is_some_and(|(s, _)| s.is_some_and(is_solid)),
        Rule::WallHangingSign => {
            // `WallHangingSignBlock.canPlace`: a sturdy face or a hanging
            // sign on either side along the sign.
            let Some(f) = facing() else { return false };
            [
                crate::blocks::facing::clockwise(f),
                crate::blocks::facing::clockwise(f).opposite(),
            ]
            .iter()
            .any(|&side| {
                at(side).is_some_and(|s| {
                    let kind = s.as_block_kind().to_str();
                    if kind.ends_with("_wall_hanging_sign") {
                        crate::blocks::info::property(s, "facing")
                            .and_then(crate::blocks::facing::from_name)
                            .is_some_and(|g| axis(g) == axis(f))
                    } else {
                        is_face_sturdy(s, side.opposite())
                    }
                })
            })
        }
        Rule::Unpredicted => false,
    }
}

/// `state.is(#<tag>)`: the server's tags, or vanilla's before it sent any.
fn in_tag(state: BlockState, tag: &str) -> bool {
    if crate::blocks::tags::loaded() {
        return crate::blocks::tags::has(state, tag);
    }
    use azalea_registry::tags::blocks as T;
    let vanilla: &azalea_registry::tags::RegistryTag<BlockKind> = match tag {
        "cannot_support_seagrass" => &T::CANNOT_SUPPORT_SEAGRASS,
        "cannot_support_snow_layer" => &T::CANNOT_SUPPORT_SNOW_LAYER,
        "overrides_mushroom_light_requirement" => &T::OVERRIDES_MUSHROOM_LIGHT_REQUIREMENT,
        "support_override_cactus_flower" => &T::SUPPORT_OVERRIDE_CACTUS_FLOWER,
        "support_override_snow_layer" => &T::SUPPORT_OVERRIDE_SNOW_LAYER,
        "supports_azalea" => &T::SUPPORTS_AZALEA,
        "supports_bamboo" => &T::SUPPORTS_BAMBOO,
        "supports_big_dripleaf" => &T::SUPPORTS_BIG_DRIPLEAF,
        "supports_cactus" => &T::SUPPORTS_CACTUS,
        "supports_cocoa" => &T::SUPPORTS_COCOA,
        "supports_crimson_fungus" => &T::SUPPORTS_CRIMSON_FUNGUS,
        "supports_crimson_roots" => &T::SUPPORTS_CRIMSON_ROOTS,
        "supports_crops" => &T::SUPPORTS_CROPS,
        "supports_dry_vegetation" => &T::SUPPORTS_DRY_VEGETATION,
        "supports_mangrove_propagule" => &T::SUPPORTS_MANGROVE_PROPAGULE,
        "supports_melon_stem" => &T::SUPPORTS_MELON_STEM,
        "supports_nether_sprouts" => &T::SUPPORTS_NETHER_SPROUTS,
        "supports_nether_wart" => &T::SUPPORTS_NETHER_WART,
        "supports_pumpkin_stem" => &T::SUPPORTS_PUMPKIN_STEM,
        "supports_small_dripleaf" => &T::SUPPORTS_SMALL_DRIPLEAF,
        "supports_sugar_cane" => &T::SUPPORTS_SUGAR_CANE,
        "supports_sugar_cane_adjacently" => &T::SUPPORTS_SUGAR_CANE_ADJACENTLY,
        "supports_vegetation" => &T::SUPPORTS_VEGETATION,
        "supports_warped_fungus" => &T::SUPPORTS_WARPED_FUNGUS,
        "supports_warped_roots" => &T::SUPPORTS_WARPED_ROOTS,
        "supports_wither_rose" => &T::SUPPORTS_WITHER_ROSE,
        _ => return false,
    };
    vanilla.contains(&state.as_block_kind())
}

fn axis(d: Direction) -> u8 {
    match d {
        Direction::Up | Direction::Down => 0,
        Direction::North | Direction::South => 1,
        Direction::East | Direction::West => 2,
    }
}

fn state_at(block_at: &dyn Fn(BlockPos) -> Option<BlockState>, pos: BlockPos) -> BlockState {
    block_at(pos).unwrap_or(BlockState::AIR)
}

fn water_source(state: BlockState) -> bool {
    let fluid = FluidState::from(state);
    fluid.kind == FluidKind::Water && fluid.amount == 8 && !fluid.falling
}

fn is_water_any(state: BlockState) -> bool {
    FluidState::from(state).kind == FluidKind::Water
}

fn is_lava(state: BlockState) -> bool {
    FluidState::from(state).kind == FluidKind::Lava
}

/// `getRawBrightness(pos, 0)`, or `None` where the client has no light yet.
fn raw_light(pos: BlockPos) -> Option<u8> {
    let (sky, block) = sky_and_block(pos)?;
    Some(sky.max(block))
}

fn sky_and_block(pos: BlockPos) -> Option<(u8, u8)> {
    let map = crate::client::worldsync::light_map().read();
    map.knows(pos.x, pos.y, pos.z)
        .then(|| map.at(pos.x, pos.y, pos.z))
}

/// `CropBlock.hasSufficientLight`: light 8+ or open sky (unknown light
/// passes; the server decides).
fn crop_light(pos: BlockPos) -> bool {
    sky_and_block(pos).is_none_or(|(sky, block)| sky.max(block) >= 8 || sky == 15)
}
